macro_rules! deps {
    () => {
        Chunks!();
        Split!();
        RChunksExact!();
        Windows!();
        ChunkBy!();
        ChunksExact!();
        RChunks!();
        SplitInclusive!();
    };
}

macro_rules! ParallelSlice {
    () => {
        deps!();
        # [doc = " Parallel extensions for slices."] pub trait ParallelSlice < T : Sync > { # [doc = " Returns a plain slice, which is used to implement the rest of the"] # [doc = " parallel methods."] fn as_parallel_slice (& self) -> & [T] ; # [doc = " Returns a parallel iterator over subslices separated by elements that"] # [doc = " match the separator."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let products: Vec<_> = [1, 2, 3, 0, 2, 4, 8, 0, 3, 6, 9]"] # [doc = "     .par_split(|i| *i == 0)"] # [doc = "     .map(|numbers| numbers.iter().product::<i32>())"] # [doc = "     .collect();"] # [doc = " assert_eq!(products, [6, 64, 162]);"] # [doc = " ```"] fn par_split < P > (& self , separator : P) -> Split < '_ , T , P > where P : Fn (& T) -> bool + Sync + Send , { Split { slice : self . as_parallel_slice () , separator , } } # [doc = " Returns a parallel iterator over subslices separated by elements that"] # [doc = " match the separator, including the matched part as a terminator."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let lengths: Vec<_> = [1, 2, 3, 0, 2, 4, 8, 0, 3, 6, 9]"] # [doc = "     .par_split_inclusive(|i| *i == 0)"] # [doc = "     .map(|numbers| numbers.len())"] # [doc = "     .collect();"] # [doc = " assert_eq!(lengths, [4, 4, 3]);"] # [doc = " ```"] fn par_split_inclusive < P > (& self , separator : P) -> SplitInclusive < '_ , T , P > where P : Fn (& T) -> bool + Sync + Send , { SplitInclusive { slice : self . as_parallel_slice () , separator , } } # [doc = " Returns a parallel iterator over all contiguous windows of length"] # [doc = " `window_size`. The windows overlap."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let windows: Vec<_> = [1, 2, 3].par_windows(2).collect();"] # [doc = " assert_eq!(vec![[1, 2], [2, 3]], windows);"] # [doc = " ```"] fn par_windows (& self , window_size : usize) -> Windows < '_ , T > { Windows { window_size , slice : self . as_parallel_slice () , } } # [doc = " Returns a parallel iterator over at most `chunk_size` elements of"] # [doc = " `self` at a time. The chunks do not overlap."] # [doc = ""] # [doc = " If the number of elements in the iterator is not divisible by"] # [doc = " `chunk_size`, the last chunk may be shorter than `chunk_size`.  All"] # [doc = " other chunks will have that exact length."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let chunks: Vec<_> = [1, 2, 3, 4, 5].par_chunks(2).collect();"] # [doc = " assert_eq!(chunks, vec![&[1, 2][..], &[3, 4], &[5]]);"] # [doc = " ```"] # [track_caller] fn par_chunks (& self , chunk_size : usize) -> Chunks < '_ , T > { assert ! (chunk_size != 0 , "chunk_size must not be zero") ; Chunks :: new (chunk_size , self . as_parallel_slice ()) } # [doc = " Returns a parallel iterator over `chunk_size` elements of"] # [doc = " `self` at a time. The chunks do not overlap."] # [doc = ""] # [doc = " If `chunk_size` does not divide the length of the slice, then the"] # [doc = " last up to `chunk_size-1` elements will be omitted and can be"] # [doc = " retrieved from the remainder function of the iterator."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let chunks: Vec<_> = [1, 2, 3, 4, 5].par_chunks_exact(2).collect();"] # [doc = " assert_eq!(chunks, vec![&[1, 2][..], &[3, 4]]);"] # [doc = " ```"] # [track_caller] fn par_chunks_exact (& self , chunk_size : usize) -> ChunksExact < '_ , T > { assert ! (chunk_size != 0 , "chunk_size must not be zero") ; ChunksExact :: new (chunk_size , self . as_parallel_slice ()) } # [doc = " Returns a parallel iterator over at most `chunk_size` elements of `self` at a time,"] # [doc = " starting at the end. The chunks do not overlap."] # [doc = ""] # [doc = " If the number of elements in the iterator is not divisible by"] # [doc = " `chunk_size`, the last chunk may be shorter than `chunk_size`.  All"] # [doc = " other chunks will have that exact length."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let chunks: Vec<_> = [1, 2, 3, 4, 5].par_rchunks(2).collect();"] # [doc = " assert_eq!(chunks, vec![&[4, 5][..], &[2, 3], &[1]]);"] # [doc = " ```"] # [track_caller] fn par_rchunks (& self , chunk_size : usize) -> RChunks < '_ , T > { assert ! (chunk_size != 0 , "chunk_size must not be zero") ; RChunks :: new (chunk_size , self . as_parallel_slice ()) } # [doc = " Returns a parallel iterator over `chunk_size` elements of `self` at a time,"] # [doc = " starting at the end. The chunks do not overlap."] # [doc = ""] # [doc = " If `chunk_size` does not divide the length of the slice, then the"] # [doc = " last up to `chunk_size-1` elements will be omitted and can be"] # [doc = " retrieved from the remainder function of the iterator."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let chunks: Vec<_> = [1, 2, 3, 4, 5].par_rchunks_exact(2).collect();"] # [doc = " assert_eq!(chunks, vec![&[4, 5][..], &[2, 3]]);"] # [doc = " ```"] # [track_caller] fn par_rchunks_exact (& self , chunk_size : usize) -> RChunksExact < '_ , T > { assert ! (chunk_size != 0 , "chunk_size must not be zero") ; RChunksExact :: new (chunk_size , self . as_parallel_slice ()) } # [doc = " Returns a parallel iterator over the slice producing non-overlapping runs"] # [doc = " of elements using the predicate to separate them."] # [doc = ""] # [doc = " The predicate is called on two elements following themselves,"] # [doc = " it means the predicate is called on `slice[0]` and `slice[1]`"] # [doc = " then on `slice[1]` and `slice[2]` and so on."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = " let chunks: Vec<_> = [1, 2, 2, 3, 3, 3].par_chunk_by(|&x, &y| x == y).collect();"] # [doc = " assert_eq!(chunks[0], &[1]);"] # [doc = " assert_eq!(chunks[1], &[2, 2]);"] # [doc = " assert_eq!(chunks[2], &[3, 3, 3]);"] # [doc = " ```"] fn par_chunk_by < F > (& self , pred : F) -> ChunkBy < '_ , T , F > where F : Fn (& T , & T) -> bool + Send + Sync , { ChunkBy :: new (self . as_parallel_slice () , pred) } }
    };
}

ParallelSlice!();